   190	// runVerifyShell executes one command in the repository. It returns the exit code separately from the
   191	// error: a test suite exiting non-zero is the normal case and not a failure of this verb.
   192	func runVerifyShell(ctx context.Context, repo, command string) (string, int, error) {
   193		cmd := exec.CommandContext(ctx, "sh", "-c", command)
   194		cmd.Dir = repo
   195		// The verb MUST NOT mutate the tree beyond what the command itself does, so nothing is written, no
   196		// files are staged and no environment is injected beyond the caller's own.
   197		out, err := cmd.CombinedOutput()
   198		if err != nil {
   199			var exit *exec.ExitError
   200			if errorsAs(err, &exit) {
   201				return string(out), exit.ExitCode(), nil
   202			}
   203			return string(out), 0, err
   204		}
   205		return string(out), 0, nil
   206	}
